using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace CampaignDemo.Editor {
 [InitializeOnLoad]public static class ContourRevisionVerification {
  const string Key="ContourRevisionVerification";static double start;static int phase;static int buildCount;static int textureId;static readonly List<string> rows=new List<string>();
  static string Root {get{var p=Path.GetFullPath(Path.Combine(Application.dataPath,"../VerificationOutputs"));Directory.CreateDirectory(p);return p;}}
  static ContourRevisionVerification(){if(SessionState.GetBool(Key,false)){start=EditorApplication.timeSinceStartup;EditorApplication.update+=Poll;}}
  static void Check(bool ok,string name){if(!ok)throw new Exception(name);rows.Add("PASS "+name);Debug.Log("CONTOUR_PASS "+name);}
  public static void Run(){try{Prepare();File.WriteAllLines(Path.Combine(Root,"contour-edit-verification.txt"),rows);SessionState.SetBool(Key,true);start=EditorApplication.timeSinceStartup;EditorApplication.update+=Poll;EditorApplication.isPlaying=true;}catch(Exception e){Finish(e);}}
  public static void RunBake(){try{Prepare();File.WriteAllLines(Path.Combine(Root,"contour-edit-verification.txt"),rows);EditorApplication.Exit(0);}catch(Exception e){Finish(e);}}
  public static void RunRuntime(){EditorSceneManager.OpenScene("Assets/Scenes/DoubleValley9x.unity");SessionState.SetBool(Key,true);start=EditorApplication.timeSinceStartup;EditorApplication.update+=Poll;EditorApplication.isPlaying=true;}
  static void Prepare(){var scene=EditorSceneManager.OpenScene("Assets/Scenes/DoubleValley9x.unity");var cart=UnityEngine.Object.FindObjectOfType<StaffMapCartography>();var data=UnityEngine.Object.FindObjectOfType<MapDetailRegions>();data.Resolve();string terrain=JsonUtility.ToJson(data.terrain.definition),roads=JsonUtility.ToJson(data.roads.definition),areas=JsonUtility.ToJson(data);int count=data.areas.Count;float wear=cart.wear,fold=cart.foldStrength;
   data.generateFarmland=false;MapDetailBaker.Bake(data);Check(data.generatedFields==0&&!data.generateFarmland,"farmland hidden without deleting editable area data");Check(data.areas.Count==count&&count>0,"original authoring regions retained");Check(data.generatedBuildings>0,"village decoration remains when fields are hidden");
   string cache=AssetDatabase.GetAssetPath(cart.bakedBackground);cart.Rebuild();var settlements=cart.SettlementInk;Check(settlements!=null&&settlements.CityAnchors>0&&settlements.ResourceAnchors==UnityEngine.Object.FindObjectsOfType<ResourceSite>().Count(s=>s.gameObject.scene==scene),"clustered villages decorate cities and every resource site");Check(settlements.houses.Select(h=>h.shape).Distinct().Count()==3,"villages contain square rectangular and L shaped buildings");Debug.Log("VILLAGE_INFO clusters="+settlements.ClusterCount+" houses="+settlements.houses.Count+" cityAnchors="+settlements.CityAnchors+" resourceAnchors="+settlements.ResourceAnchors);var field=cart.ContourInk;Check(field!=null&&field.MountainStrokes>100&&field.ForestStrokes>100,"height field generates mountain and decorative forest contours");
   foreach(var stroke in field.strokes){if(!field.RoadClear(stroke.a)||!field.RoadClear(stroke.b)||!field.RoadClear((stroke.a+stroke.b)*.5f))throw new Exception("Contour crosses road surface");}Check(true,"all emitted contours keep clear of roads");Check(field.strokes.Count(s=>s.forest&&data.terrain.TerrainAt(new RoadPoint((s.a.x+s.b.x)*.5f,(s.a.y+s.b.y)*.5f))==TerrainKind.Ground)>100,"sparse decorative forest contours extend into plain ground");
   foreach(var edge in data.roads.definition.connections)for(int i=0;i<=12;i++){Vector2 p=data.terrain.transform.InverseTransformPoint(data.roads.transform.TransformPoint(Vector2.Lerp(data.roads.definition.nodes[edge.a],data.roads.definition.nodes[edge.b],i/12f)));if(field.HeightAt(p)>.00001f)throw new Exception("Road datum is not level");}Check(true,"entire road network shares level decorative height datum");
   var mountain=data.terrain.definition.regions.First(r=>r.terrain==TerrainKind.HighMountain);Vector2 center=Vector2.zero;foreach(var p in mountain.polygon)center+=p;center/=mountain.polygon.Length;float peak=0;for(float y=-3;y<=3;y+=.4f)for(float x=-3;x<=3;x+=.4f)peak=Mathf.Max(peak,field.HeightAt(center+new Vector2(x,y)));Check(peak>1.5f&&field.HeightAt(new Vector2(data.terrain.definition.bounds.xMin+.1f,data.terrain.definition.bounds.yMin+.1f))<peak,"mountain heights descend into surrounding lowland");
   Check(terrain==JsonUtility.ToJson(data.terrain.definition)&&roads==JsonUtility.ToJson(data.roads.definition),"visual heights leave terrain types road traversal and combat data unchanged");Check(cart.wear==wear&&cart.foldStrength==fold,"paper wear folds and ink character preserved");
   File.WriteAllBytes(cache,cart.Texture.EncodeToPNG());AssetDatabase.ImportAsset(cache,ImportAssetOptions.ForceUpdate);cart.bakedBackground=AssetDatabase.LoadAssetAtPath<Sprite>(cache);cart.ShowBakedBackground();data.GetComponent<StaffRoadOverlay>().Rebuild();EditorUtility.SetDirty(cart);EditorUtility.SetDirty(data);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();var b=data.terrain.definition.bounds;Capture(b.center,b.height*.5f,3072,1920,"contour-overview.png");var forest=data.terrain.definition.regions.First(r=>r.terrain==TerrainKind.Forest);Vector2 fp=Vector2.zero;foreach(var p in forest.polygon)fp+=p;fp/=forest.polygon.Length;Capture(fp,4,1600,1000,"contour-forest-preview.png");var resource=UnityEngine.Object.FindObjectsOfType<ResourceSite>().First(s=>s.gameObject.scene==scene);Vector2 villageFocus=data.terrain.transform.InverseTransformPoint(resource.transform.position);Capture(villageFocus,3.2f,1600,1000,"village-resource-preview.png");rows.Add("INFO mountainStrokes="+field.MountainStrokes+" forestStrokes="+field.ForestStrokes);
  }
  static void Poll(){try{if(EditorApplication.timeSinceStartup-start>160)throw new Exception("Runtime verification timeout");if(!EditorApplication.isPlaying||Time.time<.8f)return;var w=UnityEngine.Object.FindObjectOfType<BattleWorld>();if(w==null||!w.Initialized)return;var cart=UnityEngine.Object.FindObjectOfType<StaffMapCartography>();if(phase==0){w.enabled=false;foreach(var ai in w.GetComponents<BattleAIController>())ai.enabled=false;foreach(var ai in w.GetComponents<AIBasicCommander>())ai.enabled=false;w.GetComponent<LocalTacticalBattle>().enabled=false;w.fogEnabled=false;w.SetPlayer("A");var marks=w.GetComponent<DeathScorchMarks>();Check(marks!=null,"death crater component attached in live game");marks.Clear();foreach(var u in w.units)u.Motor?.Stop();var unit=w.units.First(u=>u.Alive&&u.ownerId=="A");if(unit.Point!=null)unit.BeginExit();Check(unit.OnMap,"test army exits garrison before field death");unit.transform.position=new Vector3(-12,-5,0);marks.Observe();unit.Eliminate();marks.Observe();Check(marks.Count==1,"actual army elimination creates one crater");var mark=marks.Oldest;Check(mark.enabled&&mark.sortingOrder>3&&Vector2.Distance(mark.transform.position,unit.transform.position)<.001f,"crater is visible above map at death position");var pixel=mark.sprite.texture.GetPixel(32,32);Debug.Log("CRATER_PIXEL "+pixel+" size="+mark.sprite.texture.width+"x"+mark.sprite.texture.height);Check(pixel.r<.12f&&pixel.g<.12f&&pixel.b<.12f&&pixel.a>.20f,"death crater has dark charcoal core");marks.Observe();Check(marks.Count==1,"repeated death observation does not duplicate crater");Capture(unit.transform.position,.9f,1200,800,"death-crater-preview.png");buildCount=cart.BuildCount;textureId=cart.bakedBackground.GetInstanceID();start=EditorApplication.timeSinceStartup;phase=1;return;}
   if(EditorApplication.timeSinceStartup-start<1)return;Check(cart.BuildCount==buildCount&&buildCount==0&&cart.bakedBackground.GetInstanceID()==textureId,"runtime uses fixed cached contour texture without rebuilding");Check(!UnityEngine.Object.FindObjectOfType<MapDetailRegions>().generateFarmland,"farmland remains hidden after game starts");Finish(null);
  }catch(Exception e){Finish(e);}}
  static void Capture(Vector2 focus,float size,int width,int height,string name){var camera=UnityEngine.Object.FindObjectOfType<BattleWorld>().setup.mapCamera;var position=camera.transform.position;float zoom=camera.orthographicSize,aspect=camera.aspect;var target=camera.targetTexture;var rt=new RenderTexture(width,height,24);camera.transform.position=new Vector3(focus.x,focus.y,-20);camera.orthographicSize=size;camera.aspect=width/(float)height;camera.targetTexture=rt;camera.Render();var active=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(width,height,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,width,height),0,0);image.Apply();File.WriteAllBytes(Path.Combine(Root,name),image.EncodeToPNG());RenderTexture.active=active;camera.targetTexture=target;camera.transform.position=position;camera.orthographicSize=zoom;camera.aspect=aspect;UnityEngine.Object.DestroyImmediate(image);rt.Release();UnityEngine.Object.DestroyImmediate(rt);}
  static void Finish(Exception error){if(error!=null){rows.Add("FAIL "+error);Debug.LogException(error);}File.WriteAllLines(Path.Combine(Root,"contour-runtime-verification.txt"),rows);SessionState.SetBool(Key,false);EditorApplication.update-=Poll;EditorApplication.Exit(error==null?0:1);}
 }
}





